        "scope_ruling_sha256": HASHES["EVO883-EVO886-minimum-scope-ruling-v1.json"],
        **snapshot.policy_binding(),
        "source_files": sources,
        "source_sha256": snapshot.digest(sources),
        "import_graph": graph,
