            sum(isinstance(n, ast.Name) and n.id == "compile" for n in ast.walk(tree))
            != 0
        ):
            raise ValueError
        if (
            sum(
                isinstance(n, ast.Name)
                and n.id == "self_raw"
                and isinstance(n.ctx, ast.Load)
                for n in ast.walk(fn)
            )
            != 1
        ):
            raise ValueError
        if (
            sum(
                isinstance(n, ast.Name)
                and n.id == "self_path"
                and isinstance(n.ctx, ast.Store)
                for n in ast.walk(fn)
            )
            != 1
        ):
            raise ValueError
        audit_fn = next(
            n
            for n in audit_tree.body
            if isinstance(n, ast.FunctionDef) and n.name == "b2_isolation_proof"
        )
        audit_loop = ast.parse(
            'for _, relative, expected in B_RELEASE_ADAPTER_READS:\n    raw = Path.read_bytes(root / relative)\n    if sha256(raw) != expected:\n        raise ValueError("scope.file_access_not_whitelisted")'
        ).body[0]
        if sum(ast.dump(n) == ast.dump(audit_loop) for n in audit_fn.body) != 1:
            raise ValueError
        loops = [
            n
            for n in ast.walk(fn)
            if isinstance(n, ast.For)
            and ast.dump(n.iter)
            == ast.dump(ast.parse("original_sha256.items()", mode="eval").body)
        ]
        if len(loops) != 1 or ast.dump(loops[0].target) != ast.dump(
            ast.parse("for name, expected in original_sha256.items(): pass")
            .body[0]
            .target
        ):
            raise ValueError
    except (ValueError, TypeError, KeyError, StopIteration, AttributeError) as exc:
        raise ValueError("scope.file_access_not_whitelisted") from exc
    return {
        "sha256_reads": [dict(module=m, path=p, sha256=s) for m, p, s in rows],
        "path_only_reads": [
            dict(module=m, path=p) for m, p in B_RELEASE_PATH_ONLY_READS
        ],
        "exact_adapter_read_sites": 3,
        "self_read_argument": "self_path = Path(_read_trusted_release.__code__.co_filename).resolve()",
        "self_read_use": "co_filename / resolved __file__ equality; fixed self bytes SHA -> implementation_id",
        "import_filename_path_binding": True,
        "post_import_process_tamper_defense": False,
        "additional_fixed_audit_read_sites": 1,
        "additional_fixed_compile_sites": 0,
        "dynamic_code_exceptions": [],
        "root_sha_in_code": False,
    }

audit_function_templates._b_release_audit_structure:
_b_release_audit_structure(tree):
    """The audit source accepts only its reviewed functions and literal data."""
    expected_bindings = {'GATES': GATES, 'IMPORTS': IMPORTS, 'FIXED_READS': FIXED_READS, 'B_RELEASE_FIXED_READS': B_RELEASE_FIXED_READS, 'B_RELEASE_ADAPTER_READS': B_RELEASE_ADAPTER_READS, 'B_RELEASE_PATH_ONLY_READS': B_RELEASE_PATH_ONLY_READS, 'B_RELEASE_MODULE_TEMPLATE': B_RELEASE_MODULE_TEMPLATE, 'B_RELEASE_FIXED_LITERALS': B_RELEASE_FIXED_LITERALS, 'B_RELEASE_DEPENDENCY_SOURCES': B_RELEASE_DEPENDENCY_SOURCES, 'FIXED_READER_SOURCES': FIXED_READER_SOURCES, 'FILENAME_READS': FILENAME_READS, 'FILENAME_SOURCE_IDENTITIES': FILENAME_SOURCE_IDENTITIES, 'B_RELEASE_AUDIT_FUNCTIONS': B_RELEASE_AUDIT_FUNCTIONS}
    assignments = [n for n in tree.body if isinstance(n, ast.Assign)]
    functions = [n for n in tree.body if isinstance(n, ast.FunctionDef)]
    imports = [n for n in tree.body if isinstance(n, (ast.Import, ast.ImportFrom))]
    if len(tree.body) != len(assignments) + len(functions) + len(imports) + 1:
        raise ValueError
    if not isinstance(tree.body[0], ast.Expr) or ast.dump(tree.body[0]) != ast.dump(ast.parse("'Static import/guard/read-scope receipt for owned trusted strategy interfaces.'").body[0]):
        raise ValueError
    if [ast.dump(n) for n in imports] != [ast.dump(n) for n in ast.parse('import ast\nfrom pathlib import Path\nfrom .contract import digest, sha256\nfrom .input_scope import ROLES').body]:
        raise ValueError
    seen = set()
    for node in assignments:
        if len(node.targets) != 1 or not isinstance(node.targets[0], ast.Name):
            raise ValueError
        name = node.targets[0].id
        if name in seen or name not in expected_bindings or ast.literal_eval(node.value) != expected_bindings[name]:
            raise ValueError
        seen.add(name)
    if seen != set(expected_bindings):
        raise ValueError
    if len(functions) != len(B_RELEASE_AUDIT_FUNCTIONS) or {
        node.name: ast.dump(node, include_attributes=False) for node in functions
    } != {
        name: ast.dump(ast.parse("def " + source).body[0], include_attributes=False)
        for name, source in B_RELEASE_AUDIT_FUNCTIONS.items()
    }:
        raise ValueError

