    )

audit_function_templates.noncash_isolation_proof:
noncash_isolation_proof(policy):
    """Inspect owned economic boundaries; this does not attest a real account."""
    from .noncash_v3 import (
        ROUTES,
        CONSUMERS,
        actor_ids,
        ACCEPTED_CATALOG_SHA256,
        CATALOG_REASON,
    )

    root = Path(__file__).parent
    names = (
        "noncash_v3",
        "catalog_v21",
        "catalog_members",
        "reference_noncash",
        "isolation",
        "execution",
        "valuation",
        "k5",
        "folds",
    )
    raw_sources = {name: (root / (name + ".py")).read_bytes() for name in names}
    trees = {name: ast.parse(raw) for name, raw in raw_sources.items()}

    def function(module, name):
        return next(
            n
            for n in trees[module].body
            if isinstance(n, ast.FunctionDef) and n.name == name
        )

    def calls(node, name):
        return sorted(
            n.lineno
            for n in ast.walk(node)
            if isinstance(n, ast.Call)
            and isinstance(n.func, ast.Name)
            and n.func.id == name
        )

    numeric = function("noncash_v3", "guarded_value")
    guards = calls(numeric, "assert_consumer_symbols")
    readers = calls(numeric, "reader")
    if len(guards) != 1 or len(readers) != 1 or guards[0] >= readers[0]:
        raise ValueError("B.static_numeric_guard_not_dominant")
    economic = function("noncash_v3", "economic_values")
    if min(calls(economic, "assert_consumer_symbols"), default=10**9) >= min(
        calls(economic, "guarded_value"), default=-1
    ):
        raise ValueError("B.static_batch_guard_missing")
    # A pure injected reader is the only numeric boundary in this module.
    forbidden = {
        "open",
        "read_bytes",
        "read_text",
        "write_bytes",
        "write_text",
        "glob",
        "rglob",
        "eval",
        "exec",
        "__import__",
    }
    for n in ast.walk(trees["noncash_v3"]):
        if isinstance(n, ast.Call):
            name = (
                n.func.id
                if isinstance(n.func, ast.Name)
                else n.func.attr
                if isinstance(n.func, ast.Attribute)
                else ""
            )
            if name in forbidden:
                raise ValueError("B.static_unregistered_reader")
    acquisition = function("noncash_v3", "acquisition_check")
    if (
        len(calls(acquisition, "zero_exposure")) != 2
        or not calls(acquisition, "zero_origin")
        or not calls(acquisition, "checked_guard")
    ):
        raise ValueError("B.static_acquisition_induction_missing")
    calibration = function("execution", "_v2_calibration_rows")
    voluntary = function("execution", "voluntary_trade_gate")
    valuation = function("valuation", "integer_cash_valuation")
    for node in (calibration, voluntary, valuation):
        if not calls(node, "assert_consumer_symbols"):
            raise ValueError("B.static_consumer_connection_missing")
    factor_cash = function("valuation", "factor_cash_valuation")
    if not any(
        isinstance(n, ast.Call)
        and isinstance(n.func, ast.Name)
        and n.func.id == "integer_cash_valuation"
        and any(
            k.arg == "factor_scope"
            and isinstance(k.value, ast.Constant)
            and k.value.value is True
            for k in n.keywords
        )
        for n in ast.walk(factor_cash)
    ):
        raise ValueError("B.static_factor_cash_scope_not_bound")
    marks = [
        n.lineno
        for n in ast.walk(valuation)
        if isinstance(n, ast.Subscript)
        and isinstance(n.slice, ast.Constant)
        and n.slice.value == "marks"
    ]
    if min(calls(valuation, "assert_consumer_symbols")) >= min(marks, default=-1):
        raise ValueError("B.static_valuation_read_precedes_guard")
    quote = function("k5", "vsnt_quote")
    raises = [n.lineno for n in ast.walk(quote) if isinstance(n, ast.Raise)]
    reads = [
        n.lineno
        for n in ast.walk(quote)
        if isinstance(n, ast.Call)
        and isinstance(n.func, ast.Attribute)
        and n.func.attr == "read_bytes"
    ]
    if not raises or min(raises) >= min(reads, default=-1):
        raise ValueError("B.static_v3_legacy_reader_not_closed")
    files = {n + ".py": sha256(b) for n, b in raw_sources.items()}
    payload = dict(
        schema="EVO900.factor-arm-noncash-static-proof/v3",
        source_files=files,
        source_sha256=digest(files),
        actor_ids=list(actor_ids(policy)),
        acquisition_routes=sorted(ROUTES),
        economic_consumer_roles=sorted(CONSUMERS),
        numeric_guard_line=guards[0],
        injected_reader_line=readers[0],
        B_catalog_sha256=ACCEPTED_CATALOG_SHA256,
        B_catalog_reason=CATALOG_REASON,
        scope="Owned factor and virtual-monitor input boundaries, supplied complete source states, and trusted callbacks; not an arbitrary Python OS sandbox or real-account attestation.",
        reference_producer_proof_completed=False,
        reference_producer_separate_mechanism_proof_available=True,
        reference_producer_real_runtime_proven=False,
        factor_cash_entrypoint="factor_cash_valuation",
        generic_accounting_is_factor_proof=False,
        real_origin_proofs=None,
        runtime_consumable=False,
        certifiable=False,
        **policy.binding,
    )
    return dict(payload, static_proof_sha256=digest(payload))

v8_structure.complete_module_template:
"""B01 metadata reception. No caller-mintable authority or runtime permission.

The deployment's original permission adapter is deliberately unconnected. Tests
may replace the private adapter to exercise reception; this does not certify a
real installation, source permission, A publication or a producer's proofs.
"""

import csv
from datetime import datetime
import io
import json
from weakref import WeakKeyDictionary

from .catalog_v21 import (
    BINDINGS as _CATALOG_BINDINGS,
    FIXTURES as _CATALOG_FIXTURES,
    derive as _derive_catalog,
)
from .contract import code_sha, sha256


ADOPTION_SHA256 = "V8_FIXED_LITERAL_14"
ANNOTATION_COMMENT = "01a19e47-bff6-7dc8-9d06-0ca0b4369576"
PUBLICATION_COMMENT = "01a19dda-830d-7b82-b549-b4d64129a6af"
ISSUE = "01a18a61-21a5-7763-8cd3-9c781f80499d"
_CONTEXTS = WeakKeyDictionary()


def _fail(reason):
    raise ValueError("B.release_context_" + reason)


def _pairs(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            _fail("encoding_invalid")
        result[key] = value
    return result


def _constant(value):
    _fail("encoding_invalid")


def _canonical(value):
    # Do not use contract.clean: NaN/Infinity must be rejected, never nullified.
    try:
        return json.dumps(
            value,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
    except (TypeError, ValueError, UnicodeError) as exc:
        raise ValueError("B.release_context_encoding_invalid") from exc


def _json(raw, *, canonical=False):
    if type(raw) is not bytes:
        _fail("encoding_invalid")
    try:
        value = json.loads(
            raw.decode("utf-8"), object_pairs_hook=_pairs, parse_constant=_constant
        )
    except (ValueError, UnicodeError) as exc:
        raise ValueError("B.release_context_encoding_invalid") from exc
    encoded = _canonical(value)
    if canonical and encoded != raw:
        _fail("encoding_invalid")
    return value


def _utc(value):
    if type(value) is not str or len(value) != 20 or value[19:] != "Z":
        _fail("encoding_invalid")
    if any(
        value[i] not in "0123456789"
        for i in (0, 1, 2, 3, 5, 6, 8, 9, 11, 12, 14, 15, 17, 18)
    ):
        _fail("encoding_invalid")
    try:
        parsed = datetime.strptime(value, "%Y-%m-%dT%H:%M:%SZ")
    except ValueError as exc:
        raise ValueError("B.release_context_encoding_invalid") from exc
    return parsed


def _read_trusted_release():
    """Fixed package originals and original-authority platform registration.

    C1 deliberately omits the root file. C2 installs only the platform comment
    readback after BR-A. Its content is the strict JSON registration below;
    platform created_at supplies acceptance evidence; performance is a separate event.
    No request, environment, cwd or caller parameter selects an input.
    """
    from pathlib import Path

    try:
        self_path = Path(_read_trusted_release.__code__.co_filename).resolve()
        if type(__file__) is not str or self_path != Path(__file__).resolve():
            _fail("acceptance_mismatch")
    except (NameError, AttributeError, OSError, RuntimeError, TypeError) as exc:
        raise ValueError("B.release_context_acceptance_mismatch") from exc
    try:
        root_raw = (
            Path(__file__).parent
            / "b_release_originals"
            / "trust-root-platform-readback.json"
        ).read_bytes()
    except OSError as exc:
        raise ValueError("B.release_context_trust_binding_missing") from exc
    try:
        root = _json(root_raw)
        if (
            type(root) is not dict
            or root.get("type") != "comment"
            or root.get("author_type") != "agent"
            or root.get("author_id") != "cc562115-7ef6-4b8f-b4b6-a5b7584b1340"
            or type(root.get("id")) is not str
            or not root["id"]
            or type(root.get("revision")) is not int
            or root["revision"] < 1
            or type(root.get("content")) is not str
            or root.get("issue_id") != "01a19dab-15f2-7e58-96a0-cf92c87162c2"
        ):
            _fail("trust_binding_missing")
        accepted_at = root["created_at"]
        _utc(accepted_at)
        registration = _json(root["content"].encode("utf-8"))
        if type(registration) is not dict or set(registration) != {
            "schema",
            "context_version",
            "receiver_id",
            "implementation_id",
            "r_sha256",
            "p_sha256",
            "adoption_sha256",
            "policy_binding",
            "run_time_binding",
            "purpose",
            "limitations",
        }:
            _fail("trust_binding_missing")
        if (
            registration["schema"] != "EVO884.BReleaseTrustRegistration/v1"
            or registration["receiver_id"]
            != "gongbu.original-host:5a307571-9534-4bbc-932c-93ffc9c94d73"
            or any(
                type(registration[k]) is not str or not registration[k]
                for k in ("context_version", "purpose", "limitations")
